const runtime = ($env.RUNTIME_INTERNAL_URL || '').replace(/\/$/, '');
const runtimeToken = ($env.RUNTIME_API_TOKEN || '').trim();
const botToken = ($env.TELEGRAM_BOT_TOKEN || '').trim();
const chatId = ($env.TELEGRAM_CHAT_ID || '').trim();
if (!runtime || !runtimeToken) throw new Error('Runtime notification transport is not configured');
if (!botToken || !chatId) return [{json:{status:'telegram_not_configured'}}];
const auth = {'Authorization': `Bearer ${runtimeToken}`, 'Content-Type': 'application/json'};
const request = (options) => this.helpers.httpRequest({...options, json:true});
const claimed = await request({method:'POST', url:`${runtime}/v1/notifications/claim`, headers:auth});
const event = claimed.event;
if (!event) return [{json:{status:'idle'}}];
const payload = event.payload || {};
const advisory = payload.advisory || {};
const icon = event.severity === 'success' ? '🟢' : event.severity === 'warning' ? '🟠' : '🔴';
const lines = [
  `${icon} ${advisory.title || String(event.event_type || 'platform_event').replaceAll('_', ' ').toUpperCase()}`,
  '',
  `Project: ${event.project_id || '-'}`,
  event.ticket_id ? `Ticket: ${event.ticket_id}` : null,
  event.work_order_id ? `WorkOrder: ${event.work_order_id}` : null,
  payload.job_id ? `Job: ${String(payload.job_id).slice(0, 12)}…` : null,
  advisory.phase ? `Phase: ${advisory.phase}` : null,
  advisory.reason ? `Reason: ${advisory.reason}` : null,
  '',
  advisory.summary || event.summary || 'Platform attention required.',
  advisory.cause ? `\nWhy:\n${advisory.cause}` : null,
  Array.isArray(advisory.preserved) && advisory.preserved.length ? `\nState preserved:\n${advisory.preserved.map(v => `• ${v}`).join('\n')}` : null,
  advisory.impact ? `\nImpact:\n${advisory.impact}` : null,
  Array.isArray(advisory.metrics) && advisory.metrics.length ? `\nMetrics:\n${advisory.metrics.map(m => {
    if (m && Object.prototype.hasOwnProperty.call(m, 'used') && Object.prototype.hasOwnProperty.call(m, 'limit')) return `• ${m.label || m.key}: ${m.used} / ${m.limit}`;
    return m && m.value !== undefined ? `• ${m.label || 'Value'}: ${m.value}` : null;
  }).filter(Boolean).join('\n')}` : null,
  advisory.recommended ? `\nRecommended:\n${advisory.recommended}` : null,
  event.github_url ? `\nGitHub: ${event.github_url}` : null,
].filter(v => v !== null);
const text = lines.join('\n').slice(0, 3900);
const actionButtons = [];
for (const action of (Array.isArray(payload.actions) ? payload.actions : [])) {
  const label = String(action.label || '').slice(0, 60);
  if (!label) continue;
  if (action.url && String(action.url).startsWith('https://github.com/')) {
    actionButtons.push([{text: label, url: String(action.url)}]);
    continue;
  }
  const callback = String(action.callback_data || '');
  if (/^act:[A-Za-z0-9_-]{8,60}$/.test(callback) && callback.length <= 64) {
    actionButtons.push([{text: label, callback_data: callback}]);
  }
}
const body = {chat_id:chatId, text, disable_web_page_preview:true};
if (actionButtons.length) body.reply_markup = {inline_keyboard: actionButtons};
try {
  await request({
    method:'POST',
    url:`https://api.telegram.org/bot${botToken}/sendMessage`,
    headers:{'Content-Type':'application/json'},
    body,
  });
  await request({method:'POST', url:`${runtime}/v1/notifications/${event.id}/ack`, headers:auth});
  return [{json:{status:'sent', event_id:event.id, event_type:event.event_type, actions:actionButtons.length}}];
} catch (error) {
  const reason = String(error && error.message ? error.message : error).slice(0, 500);
  try {
    await request({
      method:'POST',
      url:`${runtime}/v1/notifications/${event.id}/release`,
      headers:auth,
      body:{error:reason, retry_seconds:60},
    });
  } catch (releaseError) {
    console.error('notification_release_failed', String(releaseError && releaseError.message ? releaseError.message : releaseError));
  }
  throw error;
}
